<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\CarrierOnboarding;use App\Support\Url;Auth::requirePermission('CARRIER_REVIEW_QUEUE_VIEW');$rows=CarrierOnboarding::queue();$pageTitle='Carrier Verification Queue';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Carrier verification queue</h1><p>Pending individual and company carrier applications.</p></div><span class="badge"><?=h(count($rows))?> pending</span></div><div class="card table-wrap"><table><thead><tr><th>Reference</th><th>Type</th><th>Applicant</th><th>TIN</th><th>Licence</th><th>Insurance expiry</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['verification_case_ref'])?></td><td><?=h(str_contains($r['case_type'],'company')?'Company':'Individual')?></td><td><?=h($r['company_name']?:$r['user_name'])?></td><td><?=h($r['tin_number'])?></td><td><?=h($r['business_license_number'])?></td><td><?=h($r['insurance_expiry']?:'Not supplied')?></td><td><a href="<?=h(Url::to('operations/carrier-review.php?id='.$r['verification_case_id']))?>">Review</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="muted">No pending carrier applications.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
